using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.QuantumChannels;

internal sealed class CovariantPureProgramDimensionRefutationDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Quantum/QuantumChannels/CovariantPureProgramDimensionRefutation.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/QuantumChannels/gschwendtnerbluhmwinter2021programmability");
    private const string Question = "We leave it as an open question whether the upper bounds can be improved to match the lower ones also for pure program states.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "An irreducible representation of the dihedral group of order eight admits a mixed qubit program, while pure qubit programs fail.",
        H("Pure covariant programs do not match the mixed dimension"),
        Blocks(
            Node("IsCovariant", "Covariance", CovarianceFormula(), "PDF p. 4, Definition 10: “We call T UV-covariant if” T(Ug A Ug* ) = Vg T(A) Vg* for every A and g. Here U and V are unitary-valued MonoidHom maps. Every represented group element is explicitly coerced to Matrix before multiplication and star."),
            Node("MixedProgrammable", "Exact mixed programmability", ProgrammableFormula(false), "PDF p. 5, Definition 12: “Let H₁ and H₂ be separable Hilbert spaces. Then we call P ∈ CPTP(H₁ ⊗ Hₚ,H₂), with finite-dimensional Hₚ, an ε-programmable quantum processor for a set C ⊂ CPTP(H₁,H₂) of channels (ε-PQP_C), if for every quantum channel T ∈ C there exists a state π_T ∈ D(Hₚ) such that” one half of the diamond distance is at most ε. At ε = 0 this is equality on every input matrix. The set C here is all UV-covariant channels, and dP is the program dimension. IsDensity is the SLDSpectralEnergy predicate: positive semidefinite with trace one on Matrix. kronecker is Matrix.kronecker."),
            Node("PureProgrammable", "Exact pure programmability", ProgrammableFormula(true), "PDF p. 6, Remark 13: “In the literature, where the set of channels C often consists of isometries or even unitaries, it is customary to impose that the program state π_T is pure.” PureProgrammable uses the same processor condition with a normalized vector psi and its rankOneDensity. star psi dotProduct psi = 1 is the unit-norm convention."),
            Node("claim", "The affirmative answer", ClaimFormula(), "PDF p. 21, Section 5: “" + Question + "” G ranges over finite groups, which are compact with the discrete topology. The source's irreducibility sentence on PDF p. 3 is: “A unitary representation U of a group G on a finite-dimensional vector space H₁ is called irreducible representation (irrep) if and only if the only invariant subspaces of {Ug | g ∈ G} are {0} and the whole space.” The frozen IrredProj expresses exactly this invariant-subspace condition on EuclideanSpace; WithLp.linearEquiv transports it to the coordinate space Fin d1 → complex. The source's Theorems 25 and 31 make mixed dimension optimal at d_c = sum n_k; matching every mixed dimension therefore expresses the affirmative answer. A finite-group counterexample refutes the full compact-group question."),
            Node("result", "A negative answer", new Formula.Not(F.Id("claim")), "Take G = DihedralGroup 4, d1 = d2 = dP = 2, U generated by [[0,−1],[1,0]] and diag(1,−1), and V the trivial representation. Here the conjugate representation of U tensor V contains two copies of the irreducible conjugate of U, so d_c = 2. Averaging over the eight group elements gives trace(rho) times one half of the identity. Thus every UV-covariant channel is a replacement channel rho ↦ trace(rho) sigma. Tracing out the input implements all of them with mixed programs of dimension two. Pure programs of dimension two would have to produce the two basis targets, their equal superposition target, and one half of the identity. The qubit obstruction excludes these four outputs. This proves the dimension-two refutation. Exact pure optima in larger dimensions and the general multiplicity bounds require separate arguments.", DescribeRole.Theorem, AssessedProvenance.FromRepo(Source),
                new OpenProblemResolutionClaim(ProblemSlugRef.Create("gschwendtner-bluhm-winter-2021-pure-program-states"), ResolutionKind.Refuted)))));
    private static DocumentBlock Node(string name, string title, Formula formula, string prose,
        DescribeRole role = DescribeRole.Definition, AssessedProvenance? provenance = null,
        OpenProblemResolutionClaim? resolution = null) => Describe.Lean(
            DescribeId.Create("gbw-" + name.ToLowerInvariant()), DeclarationHandle.Create(Owner + name), H(title),
            StatementSource.FromAuthor(Disp(formula)), provenance ?? AssessedProvenance.FromLiterature(Source),
            Blocks(Paragraph(Text(prose))), role, resolution);
    private static Formula C => Seq(Mathbb, Grp(F.Id("C")));
    private static Formula N => Seq(Mathbb, Grp(F.Id("N")));
    private static Formula Call(string name, params Formula[] args) => new Formula.FunctionCall(FormulaIdentifier.Create(name), [.. args]);
    private static Formula At(Formula function, params Formula[] args) => new Formula.Apply(function, [.. args]);
    private static Formula Parenthesized(Formula body) => Seq(Open, body, Close);
    private static Formula All(string name, Formula type, Formula body) => Seq(Forall, Sp, Parenthesized(Seq(F.Id(name), Sp, Colon, Sp, type)), Comma, Sp, Parenthesized(body));
    private static Formula Ex(string name, Formula type, Formula body) => Seq(Exists, Sp, Parenthesized(Seq(F.Id(name), Sp, Colon, Sp, type)), Comma, Sp, Parenthesized(body));
    private static Formula Eq(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.Equal, b);
    private static Formula And(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.And, b);
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.Implies, b);
    private static Formula IffOf(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.Iff, b);
    private static Formula Mul(Formula a, Formula b) => new Formula.Binary(a, FormulaBinaryOperator.Multiply, b);
    private static Formula Arrow(Formula a, Formula b) => new Formula.TypeArrow(a, b);
    private static Formula Fin(Formula n) => Call("Fin", n);
    private static Formula Mat(Formula a, Formula b) => Call("Matrix", a, b, C);
    private static Formula State(Formula n) => Mat(Fin(n), Fin(n));
    private static Formula Instance(string name, Formula type, Formula body) => Seq(OpenBracket, Call(name, type), CloseBracket, Sp, body);
    private static Formula Product(Formula a, Formula b) => Seq(a, Sp, Times, Sp, b);
    private static Formula Processor(Formula d, Formula p, Formula e) => Arrow(Mat(Product(Fin(d), Fin(p)), Product(Fin(d), Fin(p))), State(e));
    private static Formula Kron(Formula a, Formula b) => Call("kronecker", a, b);
    private static Formula Pure(Formula p) => Call("rankOneDensity", p);
    private static Formula Representation(Formula g, Formula d) => Call("MonoidHom", g, Call("unitaryGroup", Fin(d), C));
    private static Formula AsMatrix(Formula a, Formula d) => Parenthesized(Seq(a, Sp, Colon, Sp, State(d)));
    private static Formula Lam(string x, Formula type, Formula body) => Parenthesized(Seq(LambdaLower, Sp, F.Id(x), Sp, Colon, Sp, type, Comma, Sp, body));
    private static Formula Parameters(Formula body)
    {
        Formula g = F.Id("G"), d1 = F.Id("d1"), d2 = F.Id("d2"), u = F.Id("U"), v = F.Id("V");
        return All("G", F.Id("Type"), Instance("Group", g,
            All("d1", N, All("d2", N, All("U", Representation(g, d1), All("V", Representation(g, d2), body))))));
    }
    private static Formula CovarianceFormula()
    {
        Formula g = F.Id("G"), d1 = F.Id("d1"), d2 = F.Id("d2"), u = F.Id("U"), v = F.Id("V");
        Formula t = F.Id("T"), h = F.Id("g"), rho = F.Id("rho");
        Formula um = AsMatrix(At(u, h), d1), vm = AsMatrix(At(v, h), d2);
        return Parameters(All("T", Arrow(State(d1), State(d2)), IffOf(Call("IsCovariant", u, v, t),
            All("g", g, All("rho", State(d1), Eq(At(t, Mul(Mul(um, rho), Call("star", um))), Mul(Mul(vm, At(t, rho)), Call("star", vm))))))));
    }
    private static Formula ProgrammableFormula(bool pure)
    {
        Formula g = F.Id("G"), d1 = F.Id("d1"), d2 = F.Id("d2"), u = F.Id("U"), v = F.Id("V");
        Formula dp = F.Id("dP"), p = F.Id("P"), t = F.Id("T"), rho = F.Id("rho"), pi = F.Id("pi"), psi = F.Id("psi");
        Formula implementation = All("rho", State(d1), Eq(At(p, Kron(rho, pure ? Pure(psi) : pi)), At(t, rho)));
        Formula program = pure
            ? Ex("psi", Arrow(Fin(dp), C), And(Eq(Call("dotProduct", Call("star", psi), psi), D(1)), implementation))
            : Ex("pi", State(dp), And(Call("IsDensity", pi), implementation));
        return Parameters(All("dP", N, IffOf(Call(pure ? "PureProgrammable" : "MixedProgrammable", u, v, dp),
            Ex("P", Processor(d1, dp, d2), And(Call("IsChannel", p), All("T", Arrow(State(d1), State(d2)),
                Imp(And(Call("IsChannel", t), Call("IsCovariant", u, v, t)), program)))))));
    }
    private static Formula ClaimFormula()
    {
        Formula g = F.Id("G"), d1 = F.Id("d1"), d2 = F.Id("d2"), u = F.Id("U"), v = F.Id("V"), dp = F.Id("dP");
        Formula body = Imp(Call("IrredProj", Lam("g", g, AsMatrix(At(u, F.Id("g")), d1))), All("dP", N,
            Imp(Call("MixedProgrammable", u, v, dp), Call("PureProgrammable", u, v, dp))));
        return IffOf(F.Id("claim"), All("G", F.Id("Type"), Instance("Group", g, Instance("Fintype", g,
            All("d1", N, All("d2", N, All("U", Representation(g, d1), All("V", Representation(g, d2), body))))))));
    }
}
